"""Embedded full dataset fallback for cloud deployments without subfolders."""
import gzip
import json
import base64

_COMPRESSED_DATA = ""

def get_embedded_contexts() -> dict[tuple[str, str], dict]:
    raw = gzip.decompress(base64.b64decode(_COMPRESSED_DATA.encode("ascii"))).decode("utf-8")
    parsed = json.loads(raw)
    res = {}
    for scope, items in parsed.items():
        for key, payload in items.items():
            res[(scope, key)] = {"version": 1, "payload": payload}
    return res
